const config = items[0].json.config;
const allLeads = [];
for (const item of items) {
  const data = item.json;
  if (Array.isArray(data)) allLeads.push(...data);
  else if (Array.isArray(data?.items)) allLeads.push(...data.items);
  else if (Array.isArray(data?.dataset)) allLeads.push(...data.dataset);
  else if (data?.defaultDatasetId) continue;
  else if (typeof data === 'object' && data !== null) allLeads.push(data);
}
return allLeads.map((lead, idx) => {
  const website = (lead.website || lead.url || lead.site || '').toString().trim();
  const cleanWebsite = website && !website.match(/^https?:\/\//) ? 'https://' + website : website;
  const domain = cleanWebsite.replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].toLowerCase();
  return {
    json: {
      lead_id: 'lead_' + Date.now() + '_' + idx,
      company_name: (lead.title || lead.name || lead.company_name || '').toString().trim(),
      website: cleanWebsite,
      domain: domain,
      business_category: (lead.categoryName || lead.category || lead.business_category || '').toString().trim(),
      industry: (lead.categoryName || config.industry || '').toString().trim(),
      address: (lead.address || lead.street || '').toString().trim(),
      city: (lead.city || '').toString().trim(),
      country: (lead.country || '').toString().trim(),
      phone: (lead.phone || lead.phoneUnformatted || lead.telephone || '').toString().replace(/[^\d+\-\s]/g, '').trim(),
      email: '',
      contact_name: '',
      job_title: '',
      source_url: (lead.url || lead.website || '').toString().trim(),
      linkedin_url: '',
      description: (lead.description || lead.about || '').toString().trim(),
      config: config,
      created_at: new Date().toISOString()
    }
  };
});

return items.map(item => {
  const lead = item.json;
  let passed = true;
  const reasons = [];
  if (!lead.company_name || lead.company_name.length < 2) { passed = false; reasons.push('Missing company name'); }
  if (!lead.website && !lead.email && !lead.phone) { passed = false; reasons.push('No contact info'); }
  if (lead.email && /(test|fake|example|noreply|temp|disposable)@/i.test(lead.email)) { passed = false; reasons.push('Bad email'); }
  if (lead.domain && /(test|fake|example)\./i.test(lead.domain)) { passed = false; reasons.push('Bad domain'); }
  return { json: { ...lead, validation_passed: passed, validation_reason: reasons.join('; ') || 'PASSED' } };
});

const seen = new Map(); const unique = [];
for (const item of items) {
  const lead = item.json;
  const keys = [
    lead.email ? lead.email.toLowerCase().trim() : null,
    lead.domain ? lead.domain.toLowerCase().trim() : null,
    lead.phone ? lead.phone.replace(/[^\d]/g, '') : null,
    lead.company_name && lead.city ? (lead.company_name + '-' + lead.city).toLowerCase().trim() : null
  ].filter(Boolean);
  let isNew = true;
  for (const key of keys) { if (seen.has(key)) { isNew = false; break; } }
  if (isNew) { for (const key of keys) seen.set(key, true); unique.push(item); }
}
return unique;

const originalItems = $items('NORM - Normalize Leads');
return items.map((item, idx) => {
  const original = originalItems[idx]?.json || {};
  const http = item.json;
  let status = 'WEBSITE_UNVERIFIED';
  if (http.statusCode >= 200 && http.statusCode < 400) status = 'VERIFIED';
  else if (http.code === 'ECONNREFUSED' || http.code === 'ENOTFOUND' || http.statusCode === 0) status = 'UNREACHABLE';
  return { json: { ...original, website_status: status, website_http_code: http.statusCode || 0 } };
});

return items.map(item => {
  const lead = item.json;
  let status = 'UNKNOWN'; let score = 0;
  let reason = 'Email not available from Google Maps. Use email verification service or Website Email Scraper actor.';
  return { json: { ...lead, email_status: status, verification_score: score, verification_reason: reason } };
});

return items.map(item => {
  const lead = item.json;
  let aiResult = {};
  const content = lead.content || lead.message?.content || lead.choices?.[0]?.message?.content || '{}';
  try {
    const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```/) || content.match(/```\s*([\s\S]*?)\s*```/);
    const jsonStr = jsonMatch ? jsonMatch[1] : content;
    aiResult = JSON.parse(jsonStr);
  } catch (e) {
    aiResult = { qualified: false, score: 0, classification: 'REJECT', reason: 'AI parse error', signals: [], automation_opportunities: [] };
  }
  return { json: { ...lead, ai_qualified: aiResult.qualified === true, ai_score: parseInt(aiResult.score) || 0, ai_classification: aiResult.classification || 'REJECT', ai_reason: aiResult.reason || 'No reason', ai_signals: Array.isArray(aiResult.signals) ? aiResult.signals : [], ai_automation_opportunities: Array.isArray(aiResult.automation_opportunities) ? aiResult.automation_opportunities : [] } };
});

return items.map(item => {
  const lead = item.json; const config = lead.config || {};
  let score = 0;
  const targetIndustry = (config.industry || '').toLowerCase();
  const leadIndustry = (lead.industry || '').toLowerCase();
  const leadCategory = (lead.business_category || '').toLowerCase();
  if (targetIndustry && (leadIndustry.includes(targetIndustry) || leadCategory.includes(targetIndustry))) score += 20;
  else if (lead.industry || lead.business_category) score += 10;
  const targetLocation = (config.location || '').toLowerCase();
  const leadLocation = ((lead.city || '') + ' ' + (lead.country || '')).toLowerCase();
  if (targetLocation && leadLocation.includes(targetLocation)) score += 15;
  else if (lead.city) score += 5;
  if (lead.website_status === 'VERIFIED') score += 15;
  else if (lead.website_status === 'WEBSITE_UNVERIFIED') score += 5;
  if (lead.email_status === 'VALID') score += 15;
  else if (lead.email_status === 'RISKY') score += 8;
  else if (lead.email_status === 'UNKNOWN') score += 5;
  score += Math.min(20, Math.round((lead.ai_score || 0) * 0.2));
  const title = (lead.job_title || '').toLowerCase();
  if (/(manager|director|head|ceo|cto|cfo|owner|founder|president|vp|chief)/i.test(title)) score += 10;
  else if (lead.contact_name) score += 5;
  if (lead.website && lead.description) score += 5;
  else if (lead.website) score += 3;
  const finalScore = Math.min(100, score);
  let classification = 'REJECT';
  if (finalScore >= 85) classification = 'HIGH_PRIORITY';
  else if (finalScore >= 70) classification = 'QUALIFIED';
  else if (finalScore >= 60) classification = 'WARM';
  else if (finalScore >= 40) classification = 'LOW';
  return { json: { ...lead, score: finalScore, classification: classification, qualified: finalScore >= (config.minimum_score || 70) } };
});

return items.map(item => {
  const lead = item.json;
  let qcResult = {};
  const content = lead.content || lead.message?.content || lead.choices?.[0]?.message?.content || '{}';
  try {
    const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```/) || content.match(/```\s*([\s\S]*?)\s*```/);
    const jsonStr = jsonMatch ? jsonMatch[1] : content;
    qcResult = JSON.parse(jsonStr);
  } catch (e) {
    qcResult = { approved: false, quality_score: 0, issues: ['Parse error'] };
  }
  return { json: { ...lead, qc_approved: qcResult.approved === true, qc_score: parseInt(qcResult.quality_score) || 0, qc_issues: Array.isArray(qcResult.issues) ? qcResult.issues : ['Unknown issue'] } };
});

return items.map(item => {
  const lead = item.json; const config = lead.config || {};
  const checks = {
    is_qualified: lead.qualified === true,
    score_ok: (lead.score || 0) >= (config.minimum_score || 70),
    email_valid: lead.email_status === 'VALID',
    email_exists: !!lead.email,
    qc_passed: lead.qc_approved === true,
    test_mode: config.test_mode === true,
    auto_send: config.auto_send === true,
    within_daily_limit: true,
    not_suppressed: true,
    already_contacted: false
  };
  const canSend = checks.is_qualified && checks.score_ok && checks.email_valid && checks.email_exists && checks.qc_passed && !checks.already_contacted && checks.within_daily_limit && checks.not_suppressed;
  return { json: { ...lead, safety_checks: checks, can_send: canSend, send_reason: canSend ? 'ALL_CHECKS_PASSED' : 'BLOCKED_BY_SAFETY' } };
});

