const startUrls = items
  .map(item => item.json.Website)
  .filter(url => url && typeof url === 'string')
  .map(url => url.trim())
  .filter(url => !url.toLowerCase().includes('google.com/maps'))
  .filter((url, index, array) => array.indexOf(url) === index)
  .map(url => ({
    url: url
  }));

return [
  {
    json: {
      startUrls: startUrls
    }
  }
];

const allItems = $input.all();
const output = [];

for (const item of allItems) {
  const data = item.json;
  let records = [];

  // Apify alag-alag formats mein data de sakta hai
  if (Array.isArray(data)) {
    records = data;
  } else if (Array.isArray(data?.dataset)) {
    records = data.dataset;
  } else if (Array.isArray(data?.items)) {
    records = data.items;
  } else if (typeof data === 'object' && data !== null) {
    records = [data];
  }

  for (const record of records) {
    // Har record ke saath uski source URL chipka do — baad mein grouping ke kaam aayegi
    output.push({
      json: {
        ...record,
        _source_url: record.url || record.website || record.pageUrl || record.sourceUrl || ''
      }
    });
  }
}

return output;

return items.map(item => {
  const lead = item.json;
  let emailResult = {};
  const content = lead.content || lead.message?.content || lead.choices?.[0]?.message?.content || '{}';
  try {
    const jsonMatch = content.match(/```json\s*([\s\S]*?)\s*```/) || content.match(/```\s*([\s\S]*?)\s*```/);
    const jsonStr = jsonMatch ? jsonMatch[1] : content;
    emailResult = JSON.parse(jsonStr);
  } catch (e) {
    emailResult = { 
      subject: 'Introduction - ' + (lead.company_name || 'Your Company'), 
      body: 'Hello ' + (lead.contact_name || 'there') + ',\n\nI wanted to reach out regarding potential automation opportunities for ' + (lead.company_name || 'your company') + '.\n\nBest regards,\n' + (lead.config?.sender_name || ''), 
      word_count: 30 
    };
  }
  return { json: { ...lead, email_subject: emailResult.subject || 'Introduction', email_body: emailResult.body || '', email_word_count: emailResult.word_count || 0 } };
});

// ============================================
// STEP 1: Original leads uthao (Google Maps se pehle aaye hue)
// ============================================
const originalLeads = $items('DEDUP - Remove Duplicates').map(i => i.json);

// ============================================
// STEP 2: Apify output lo (current input)
// ============================================
const apifyItems = $input.all().map(i => i.json);

// ============================================
// STEP 3: Apify data ko domain ke hisaab se group karo
// ============================================
const enrichedByDomain = {};

for (const item of apifyItems) {
  // Domain nikalo source URL se
  const rawUrl = item._source_url || item.sourceUrl || item.source_url || item.url || '';
  let domain = '';
  try {
    domain = new URL(rawUrl).hostname.replace(/^www\./, '').toLowerCase();
  } catch (e) {
    domain = rawUrl.toLowerCase()
      .replace(/^https?:\/\//, '')
      .replace(/^www\./, '')
      .split('/')[0];
  }

  if (!domain || domain === 'google.com') continue;

  if (!enrichedByDomain[domain]) {
    enrichedByDomain[domain] = {
      emails: new Set(),
      phones: new Set(),
      linkedins: new Set(),
      facebook: new Set(),
      twitter: new Set(),
      instagram: new Set(),
      youtube: new Set(),
      tiktok: new Set(),
      whatsapp: new Set(),
      pinterest: new Set()
    };
  }

  const g = enrichedByDomain[domain];

  // Emails
  if (Array.isArray(item.emails)) {
    item.emails.forEach(e => {
      if (e && typeof e === 'string' && e.includes('@')) {
        g.emails.add(e.trim().toLowerCase());
      }
    });
  }

  // Phones (clean bhi karo)
  if (Array.isArray(item.phones)) {
    item.phones.forEach(p => {
      if (p && typeof p === 'string') {
        const clean = p.trim().replace(/\\n/g, ' ').replace(/\s+/g, ' ');
        if (clean.length > 5) g.phones.add(clean);
      }
    });
  }

  // Socials (Apify format: { linkedin: [{url, handle}, ...] })
  if (item.socials && typeof item.socials === 'object' && !Array.isArray(item.socials)) {
    const map = {
      linkedin: g.linkedins,
      facebook: g.facebook,
      twitter: g.twitter,
      instagram: g.instagram,
      youtube: g.youtube,
      tiktok: g.tiktok,
      whatsapp: g.whatsapp,
      pinterest: g.pinterest
    };

    for (const [platform, targetSet] of Object.entries(map)) {
      const entries = item.socials[platform];
      if (Array.isArray(entries)) {
        entries.forEach(entry => {
          if (entry && typeof entry === 'object' && entry.url) {
            targetSet.add(entry.url.trim());
          }
        });
      }
    }
  }
}

// ============================================
// STEP 4: Original leads ke saath merge karo
// ============================================
const result = [];

for (const lead of originalLeads) {
  const leadDomain = (lead.domain || '').toLowerCase();
  const leadWebsite = (lead.website || '').toLowerCase();

  // Pehle exact domain match karo
  let enr = enrichedByDomain[leadDomain];

  // Agar na mile toh website hostname se try karo
  if (!enr && leadWebsite) {
    try {
      const host = new URL(leadWebsite).hostname.replace(/^www\./, '').toLowerCase();
      enr = enrichedByDomain[host];
    } catch (e) {}
  }

  // Sets ko arrays mein convert karo
  const e = enr ? Array.from(enr.emails) : [];
  const p = enr ? Array.from(enr.phones) : [];
  const li = enr ? Array.from(enr.linkedins) : [];
  const fb = enr ? Array.from(enr.facebook) : [];
  const tw = enr ? Array.from(enr.twitter) : [];
  const ig = enr ? Array.from(enr.instagram) : [];
  const yt = enr ? Array.from(enr.youtube) : [];
  const tk = enr ? Array.from(enr.tiktok) : [];
  const wa = enr ? Array.from(enr.whatsapp) : [];
  const pi = enr ? Array.from(enr.pinterest) : [];

  result.push({
    json: {
      // === ORIGINAL LEAD DATA (Priority) ===
      lead_id: lead.lead_id || '',
      company_name: lead.company_name || '',
      website: lead.website || '',
      domain: lead.domain || '',
      industry: lead.industry || '',
      business_category: lead.business_category || '',
      address: lead.address || '',
      city: lead.city || '',
      country: lead.country || '',
      phone: lead.phone || '',              // Original Google Maps phone
      contact_name: lead.contact_name || '',
      job_title: lead.job_title || '',
      description: lead.description || '',
      source_url: lead.source_url || '',
      created_at: lead.created_at || '',

      // === ENRICHED DATA (Apify se mila) ===
      // Email
      email: e[0] || '',
      all_emails: e.join(', '),

      // Phone (Apify se mila — alag field mein rakho)
      enriched_phone: p[0] || '',
      all_phones: p.join(', '),

      // Social - Primary (pehla URL)
      linkedin_url: li[0] || '',
      facebook: fb[0] || '',
      twitter: tw[0] || '',
      instagram: ig[0] || '',
      youtube: yt[0] || '',
      tiktok: tk[0] || '',
      whatsapp: wa[0] || '',
      pinterest: pi[0] || '',

      // Social - All (comma separated)
      all_linkedins: li.join(', '),
      all_facebook: fb.join(', '),
      all_twitter: tw.join(', '),
      all_instagram: ig.join(', '),
      all_youtube: yt.join(', '),
      all_tiktok: tk.join(', '),
      all_whatsapp: wa.join(', '),
      all_pinterest: pi.join(', '),

      // === Stats ===
      _emails_found: e.length,
      _phones_found: p.length,
      _socials_found: li.length + fb.length + tw.length + ig.length + yt.length + tk.length + wa.length + pi.length,
      _enriched_from_scraper: enr ? true : false
    }
  });
}

return result;

